import os
import re
from datetime import date
from decimal import Decimal, InvalidOperation

from PIL import Image, ImageOps, ImageFilter, ImageEnhance
import pytesseract
import openpyxl

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

EXCLUSION_KEYWORDS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
]

# Priority keyword groups (each group is same priority)
KEYWORD_GROUPS = [
    [r'GRAND\s+TOTAL'],
    [r'TOTAL\s*:?[ ]*RM'],
    [r'TOTAL\s+AMOUNT'],
    [
        r'TOTAL\s+DUE',
        r'AMOUNT\s+DUE',
        r'BALANCE\s+DUE',
        r'NETT\s+TOTAL',
        r'NET\s+TOTAL',
        r'\bTOTAL\b',
        r'\bAMOUNT\b',
    ],
]

TRANS_NUM = str.maketrans({
    'O': '0', 'o': '0',
    'I': '1', 'l': '1', '|': '1',
    'S': '5', 's': '5',
    'B': '8',
    'G': '6',
    'Z': '2',
})

TRANS_DATE = TRANS_NUM


def preprocess_image(img: Image.Image) -> Image.Image:
    gray = ImageOps.grayscale(img)
    gray = ImageOps.autocontrast(gray)
    gray = gray.filter(ImageFilter.SHARPEN)
    gray = ImageEnhance.Contrast(gray).enhance(2.0)
    return gray


def ocr_text(image_path: str) -> str:
    img = Image.open(image_path)
    texts = []
    texts.append(pytesseract.image_to_string(img, config='--oem 3 --psm 6'))
    try:
        proc = preprocess_image(img)
        texts.append(pytesseract.image_to_string(proc, config='--oem 3 --psm 6'))
    except Exception:
        pass
    return "\n".join(texts)


def normalize_line(line: str) -> str:
    return re.sub(r'\s+', ' ', line).strip().upper()


def is_excluded(norm_line: str) -> bool:
    return any(k in norm_line for k in EXCLUSION_KEYWORDS)


def extract_amount_from_line(line: str) -> str | None:
    num_src = line.translate(TRANS_NUM)
    # Keep only digits, separators, and spaces
    num_src = re.sub(r'[^0-9., ]', ' ', num_src)
    num_src = re.sub(r'\s+', ' ', num_src)

    # Prefer numbers with two decimals
    candidates = re.findall(r'\d[\d,]*[.,]\s*\d{2}', num_src)
    if not candidates:
        candidates = re.findall(r'\d[\d,]*[.,]\s*\d{1}', num_src)
    if not candidates:
        return None

    token = candidates[-1].replace(' ', '')

    # Normalize decimal/thousands separators
    if ',' in token and '.' in token:
        token = token.replace(',', '')
    elif ',' in token and '.' not in token:
        token = token.replace(',', '.')

    token = re.sub(r'[^0-9.]', '', token)
    if token.count('.') > 1:
        parts = token.split('.')
        token = ''.join(parts[:-1]) + '.' + parts[-1]

    if '.' in token:
        int_part, dec_part = token.split('.', 1)
        if len(dec_part) == 1:
            dec_part = dec_part + '0'
        elif len(dec_part) > 2:
            dec_part = dec_part[:2]
        token = f"{int_part}.{dec_part}"
    else:
        return None

    try:
        val = Decimal(token)
    except InvalidOperation:
        return None
    return f"{val:.2f}"


def extract_total(lines: list[str]) -> str | None:
    norm_lines = [normalize_line(l) for l in lines]

    for group in KEYWORD_GROUPS:
        patterns = [re.compile(p) for p in group]
        for i, (line, norm) in enumerate(zip(lines, norm_lines)):
            if is_excluded(norm):
                continue
            if 'TOTAL QTY' in norm or 'TOTAL QUANTITY' in norm:
                continue
            if not any(p.search(norm) for p in patterns):
                continue
            amount = extract_amount_from_line(line)
            if amount:
                return amount
            # Fallback: next line
            if i + 1 < len(lines):
                next_norm = norm_lines[i + 1]
                if not is_excluded(next_norm):
                    amount = extract_amount_from_line(lines[i + 1])
                    if amount:
                        return amount
    return None


def extract_date(text: str) -> str | None:
    t = text.translate(TRANS_DATE)
    t = t.replace('\\', '/')

    candidates = []

    # YYYY-MM-DD or YYYY/MM/DD
    for m in re.finditer(r'\b(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})\b', t):
        y, mo, d = m.group(1), m.group(2), m.group(3)
        try:
            dt = date(int(y), int(mo), int(d))
            candidates.append((m.start(), dt))
        except ValueError:
            continue

    # DD-MM-YYYY or DD/MM/YYYY or DD-MM-YY
    for m in re.finditer(r'\b(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})\b', t):
        d_s, mo_s, y_s = m.group(1), m.group(2), m.group(3)
        y = int(y_s)
        if len(y_s) == 2:
            y = 2000 + y
        try:
            dt = date(y, int(mo_s), int(d_s))
            candidates.append((m.start(), dt))
        except ValueError:
            continue

    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    return candidates[0][1].isoformat()


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tif', '.tiff', '.bmp')))
    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        text = ocr_text(path)
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        total = extract_total(lines)
        dt = extract_date(text)
        rows.append((fname, dt if dt else None, total if total else None))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for row in rows:
        ws.append(list(row))
    wb.save(OUT_PATH)


if __name__ == '__main__':
    main()
